WHERE price_requests.status >= 0



            AND price_requests.is_convert = 1


            AND price_requests.status = #{filter.status}




    AND price_requests.request_date >= STR_TO_DATE(#{filter.dateFrom}, '%Y-%m-%d')


    AND price_requests.request_date <= STR_TO_DATE(CONCAT(#{filter.dateTo}, '23:59:59'), '%Y-%m-%d %H:%i:%s')


    AND price_requests.created_by = #{filter.createdBy}


    AND price_requests.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})


    AND (
       price_requests.model LIKE CONCAT("%", #{filter.searchText}, "%")
    OR price_requests.pgroup_name LIKE CONCAT("%", #{filter.searchText}, "%")
    OR price_requests.request_code LIKE CONCAT("%", #{filter.searchText}, "%")
    )


    AND price_requests.created_by = #{userId}

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        price_requests.id DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

